          'المعالجة الخلفية للسطح طبقة حماية من الرطوبة تحفظ القطعة من تفكك الروابط داخل الحجر، وهي ضرورية في بيئة الحمامات الرطبة. كما أن ميل أرضية المغسلة نحو فتحة التصريف يمنع تجمع المياه الذي يسبب البقع والروائح. وأخيراً فإن الثقوب المحضرة مسبقاً للخلاط وصمام التصريف يجب أن تكون دقيقة ومتوافقة مع القياسات القياسية.',
