          'الصدع العميق مختلف تماماً: خط أعرض يُمسك بالظفر، يمتد في اتجاه واحد لأكثر من نصف اللوح، وقد ينتقل إلى الوجه الخلفي أو يظهر على الجهة المقابلة من الحائط. هذا الصدع يعني أن الحجر انفصل جزئياً أو كلياً في بنيته، وأن أي إصلاح سيكون حلاً تجميلياً مؤقتاً ما لم يُعالَج السبب.',
